rects={'5a':(0,1,0,1),'5b':(0,1,8,9),'5c':(13,15,0,3),'9':(12,15,12,15)}
def drect(r,c,b):
    r0,r1,c0,c1=b
    return max(r0-r,0,r-r1)+max(c0-c,0,c-c1)
out=[row[:] for row in grid]
which={}
for r in range(16):
 for c in range(16):
  if grid[r][c]==3:
   ds={k:drect(r,c,b) for k,b in rects.items()}
   k=min(ds,key=lambda x: (ds[x], 0 if x.startswith('5') else 1))
   out[r][c]=9 if k=='9' else 5
   which[(r,c)]=(k,ds)
print('\n'.join(' '.join(map(str,row)) for row in out))
print('recolored',len(which))

# Compare l1 patch distance output to euclidean distance to patches
import math
out_e=[row[:] for row in grid]
diffs=[]
for r in range(16):
 for c in range(16):
  if grid[r][c]==3:
   ds={k: math.hypot(drect(r,c,b) and max(b[0]-r,0,r-b[1]), drect(r,c,b) and max(b[2]-c,0,c-b[3])) for k,b in rects.items()}
   # better rect coordinate euclidean
   def de(b):
    r0,r1,c0,c1=b
    dr=max(r0-r,0,r-r1); dc=max(c0-c,0,c-c1)
    return math.hypot(dr,dc)
   ds={k:de(b) for k,b in rects.items()}
   k=min(ds,key=lambda x:(ds[x],0 if x.startswith('5') else 1))
   out_e[r][c]=9 if k=='9' else 5
   if out_e[r][c]!=out[r][c]:diffs.append((r,c,out[r][c],out_e[r][c],{k:round(v,2) for k,v in ds.items()}))
diffs

