for group,b in rects.items():
    label=9 if group=='9' else 5
    r0,r1,c0,c1=b
    for r in range(r0,r1+1):
      for c in range(c0,c1+1):
       if grid[r][c] !=3:
        if dist[r][c]>0:
         dist[r][c]=0;lab[r][c]=label;q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<16 and 0<=nc<16 and grid[nr][nc]!=3:
   nd=dist[r][c]+1
